package org.apache.commons.lang.math;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_49_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        Fraction fraction = Fraction.getFraction(2, 4);
        Fraction reducedFraction = fraction.reduce();
        // The expected reduced fraction of 2/4 is 1/2
        assertEquals("The fraction was not reduced correctly.", Fraction.getFraction(1, 2), reducedFraction);
    }
}

